<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 flex-1 truncate font-medium text-ui-ink-gray-900">Kehadiran</span>
			</div>
		</div>

		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<!-- ============ PEMILIH BULAN ============ -->
			<div class="flex items-center justify-between gap-3">
				<button
					type="button"
					class="flex h-10 w-10 items-center justify-center rounded-full border border-ui-line-gray-200 bg-ui-surface text-ui-ink-gray-600 transition active:bg-ui-surface-gray-100"
					title="Bulan sebelumnya"
					aria-label="Bulan sebelumnya"
					@click="geserBulan(-1)"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m15 18-6-6 6-6" />
					</svg>
				</button>

				<p class="min-w-0 truncate text-base font-semibold text-ui-ink-gray-900">
					{{ detail?.bulan_label || '…' }}
				</p>

				<button
					type="button"
					class="flex h-10 w-10 items-center justify-center rounded-full border border-ui-line-gray-200 bg-ui-surface text-ui-ink-gray-600 transition active:bg-ui-surface-gray-100"
					title="Bulan berikutnya"
					aria-label="Bulan berikutnya"
					@click="geserBulan(1)"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m9 18 6-6-6-6" />
					</svg>
				</button>
			</div>

			<!-- ============ RINGKASAN ============ -->
			<!-- Dihitung dari daftar hari di bawah, bukan permintaan kedua — angkanya
			     dijamin sama dengan yang dirinci. -->
			<div
				v-if="tertaut"
				class="mt-4 flex items-center justify-between gap-2 rounded-2xl bg-ui-surface px-4 py-3 shadow-sm"
			>
				<span class="flex items-center gap-1.5 text-sm font-semibold text-ui-ink-gray-900">
					<span class="h-2.5 w-2.5 rounded-full bg-green-500"></span>{{ jumlah.hadir }}
					Hadir
				</span>
				<span class="h-5 w-px bg-ui-surface-gray-200"></span>
				<span class="flex items-center gap-1.5 text-sm font-semibold text-ui-ink-gray-900">
					<span class="h-2.5 w-2.5 rounded-full bg-ui-surface-red-400"></span>{{ jumlah.absen }}
					Absen
				</span>
				<span class="h-5 w-px bg-ui-surface-gray-200"></span>
				<span class="flex items-center gap-1.5 text-sm font-semibold text-ui-ink-gray-900">
					<span class="h-2.5 w-2.5 rounded-full bg-ui-surface-amber-400"></span>{{ jumlah.libur }}
					Libur
				</span>
			</div>

			<!-- ============ DAFTAR HARI ============ -->
			<p v-if="loading" class="py-10 text-center text-sm text-ui-ink-gray-400">Memuat…</p>

			<pre
				v-else-if="loadError"
				class="mt-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm whitespace-pre-wrap text-ui-ink-red-700"
				>{{ loadError }}</pre
			>

			<p v-else-if="!tertaut" class="py-10 text-center text-sm text-ui-ink-gray-400">
				Akun Anda belum terhubung ke data karyawan. Minta HR mengisi User ID di Master
				Karyawan Anda.
			</p>

			<div v-else class="mt-4 space-y-2">
				<!-- Tanggal yang punya record bisa ditekan → detail lengkap (susunan
				     field mengikuti form desk). Hari tanpa record tidak menuju ke mana
				     pun, jadi dirender sebagai div biasa. -->
				<component
					:is="h.name ? 'RouterLink' : 'div'"
					v-for="h in hari"
					:key="h.tanggal"
					:to="
						h.name
							? {
									name: 'KehadiranDetail',
									params: { name: h.name },
									query: { bulan, tahun },
							  }
							: undefined
					"
					class="flex items-center gap-3 rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-3 shadow-sm"
					:class="[
						h.mendatang ? 'opacity-60' : '',
						h.name ? 'transition active:scale-[0.99]' : '',
					]"
				>
					<!-- Kotak tanggal, diberi warna ember supaya sekali lihat kelihatan -->
					<div
						class="flex h-12 w-12 shrink-0 flex-col items-center justify-center rounded-xl"
						:class="warnaKotak(h)"
					>
						<span class="text-base leading-none font-bold">{{
							h.tanggal_singkat
						}}</span>
						<span class="mt-0.5 text-[10px] leading-none">{{
							h.nama_hari.slice(0, 3)
						}}</span>
					</div>

					<div class="min-w-0 flex-1">
						<p class="truncate text-sm font-semibold text-ui-ink-gray-900">
							{{ h.status || (h.mendatang ? 'Belum berjalan' : 'Tidak ada data') }}
						</p>
						<p class="mt-0.5 truncate text-xs text-ui-ink-gray-500">{{ keterangan(h) }}</p>
					</div>

					<!-- Penanda keterlambatan: hal yang paling dicari saat membuka rincian -->
					<div class="flex shrink-0 flex-col items-end gap-1">
						<span
							v-if="h.terlambat_masuk"
							class="rounded-full bg-ui-surface-amber-50 px-2 py-0.5 text-[10px] font-semibold text-ui-ink-amber-700"
							>Telat</span
						>
						<span
							v-if="h.pulang_cepat"
							class="rounded-full bg-ui-surface-orange-50 px-2 py-0.5 text-[10px] font-semibold text-ui-ink-orange-700"
							>Pulang cepat</span
						>
					</div>

					<svg
						v-if="h.name"
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5 shrink-0 text-ui-ink-gray-300"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m9 18 6-6-6-6" />
					</svg>
				</component>
			</div>
		</div>
	</div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'

// Bulan yang sedang dilihat. Diambil dari query URL bila ada, supaya kembali
// dari halaman detail mendarat di bulan yang sama — bukan lompat ke bulan
// berjalan. Default: bulan berjalan.
const route = useRoute()
const router = useRouter()
const sekarang = new Date()
const bulan = ref(Number(route.query.bulan) || sekarang.getMonth() + 1)
const tahun = ref(Number(route.query.tahun) || sekarang.getFullYear())

const loadError = ref('')

// Rincian per tanggal untuk bulan terpilih. Karyawan tidak dikirim dari sini —
// backend menurunkannya dari Master Karyawan.user_id milik session.
const detailRes = createResource({
	url: 'juragan.api.portal.kehadiran.get_detail_kehadiran',
	method: 'GET',
	auto: true,
	makeParams: () => ({ bulan: bulan.value, tahun: tahun.value }),
	onSuccess: () => {
		loadError.value = ''
	},
	onError: (e) => {
		loadError.value = e?.messages?.[0] || e?.message || 'Gagal memuat data kehadiran.'
	},
})

const detail = computed(() => detailRes.data || null)
const hari = computed(() => detail.value?.hari || [])
const tertaut = computed(() => detail.value?.tertaut !== false)
// Muat pertama saja: saat ganti bulan data lama tetap terlihat sampai yang baru
// datang, supaya daftar tidak berkedip kosong tiap kali tombol ditekan.
const loading = computed(() => detailRes.loading && !detail.value)

// Angka ringkasan dihitung dari daftar yang sama yang dirender di bawahnya.
const jumlah = computed(() => {
	const j = { hadir: 0, absen: 0, libur: 0 }
	for (const h of hari.value) if (h.ember) j[h.ember] += 1
	return j
})

function geserBulan(arah) {
	const d = new Date(tahun.value, bulan.value - 1 + arah, 1)
	bulan.value = d.getMonth() + 1
	tahun.value = d.getFullYear()
}

watch([bulan, tahun], () => {
	detailRes.reload()
	// Bulan aktif ditulis ke URL (replace, bukan push) supaya tombol kembali
	// perangkat tidak harus menyusuri tiap bulan yang pernah dibuka.
	router.replace({ name: 'Kehadiran', query: { bulan: bulan.value, tahun: tahun.value } })
})

const WARNA_KOTAK = {
	hadir: 'bg-ui-surface-green-50 text-ui-ink-green-700',
	absen: 'bg-ui-surface-red-50 text-ui-ink-red-600',
	libur: 'bg-ui-surface-amber-50 text-ui-ink-amber-700',
}

function warnaKotak(h) {
	return WARNA_KOTAK[h.ember] || 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
}

/** Baris kedua: jam kerja bila ada, kalau tidak keterangan libur/cuti. */
function keterangan(h) {
	const bagian = []
	if (h.waktu_masuk || h.waktu_keluar)
		bagian.push(`${h.waktu_masuk || '--:--'} – ${h.waktu_keluar || '--:--'}`)
	if (h.jam_kerja) bagian.push(`${h.jam_kerja} jam`)
	if (h.jenis_cuti) bagian.push(h.jenis_cuti)
	if (!bagian.length && h.keterangan_libur) bagian.push(h.keterangan_libur)
	if (!bagian.length) bagian.push(h.nama_hari)
	return bagian.join(' · ')
}
</script>
